svg.script:

const SVG_NS = "http://www.w3.org/2000/svg";
const container = document.getElementById('sparkleContainer');
const iframeContainer = document.getElementById('iframeContainer');
const iframe = document.getElementById('contentFrame');
const svg = document.getElementById('mainSvg');

// === FUNCTIE: SVG GROOTTE AANPASSEN ===
function fitSVGToScreen() {
  const windowWidth = window.innerWidth;
  const windowHeight = window.innerHeight;

  // Zet SVG op volledig scherm
  svg.style.position = 'fixed';
  svg.style.top = '0';
  svg.style.left = '0';
  svg.style.width = windowWidth + 'px';
  svg.style.height = windowHeight + 'px';
  svg.style.margin = '0';
  svg.style.padding = '0';

  // Bereken schaal zodat de inhoud groter wordt
  const svgAspect = 1920 / 1080;
  const windowAspect = windowWidth / windowHeight;

  // Bepaal welke schaal het grootst is (zodat de SVG het scherm vult)
  let scaleX = windowWidth / 1920;
  let scaleY = windowHeight / 1080;

  // Gebruik de grootste schaal zodat de SVG het scherm vult
  // (hierdoor snijdt hij af aan de randen, maar de content is groot)
  const scale = Math.max(scaleX, scaleY);

  // Pas de viewBox aan met de berekende schaal
  const newWidth = 1920 * scale;
  const newHeight = 1080 * scale;
  const offsetX = (windowWidth - newWidth) / 2;
  const offsetY = (windowHeight - newHeight) / 2;

  // Gebruik transform om de SVG te schalen en centreren
  svg.style.transform = `translate(${offsetX}px, ${offsetY}px) scale(${scale})`;
  svg.style.transformOrigin = '0 0';

  // Zorg dat de SVG de juiste grootte heeft voor de transform
  svg.style.width = '1920px';
  svg.style.height = '1080px';
}

// === SPARKLE FUNCTIE ===
function createSparkle(x, y) {
  const sparkle = document.createElementNS(SVG_NS, "circle");
  const size = Math.random() * 4 + 2;
  sparkle.setAttribute("cx", x);
  sparkle.setAttribute("cy", y);
  sparkle.setAttribute("r", size);
  sparkle.setAttribute("class", "sparkle");
  sparkle.setAttribute("fill", Math.random() > 0.5 ? "#ffffff" : "#9db8e8");
  sparkle.setAttribute("opacity", "1");

  sparkle.style.transition = "opacity 0.3s ease, r 0.3s ease";
  container.appendChild(sparkle);

  setTimeout(() => {
    sparkle.style.opacity = "0";
    sparkle.setAttribute("r", "0");
    setTimeout(() => sparkle.remove(), 300);
  }, 300);
}

// === SPARKLES OP KLIK ===
document.addEventListener('click', function(e) {
  const rect = svg.getBoundingClientRect();
  const svgX = ((e.clientX - rect.left) / rect.width) * 1920;
  const svgY = ((e.clientY - rect.top) / rect.height) * 1080;

  for (let i = 0; i < 5; i++) {
    setTimeout(() => createSparkle(svgX + (Math.random() * 20 - 10), svgY + (Math.random() * 20 - 10)), i * 30);
  }
});

// === SHOW IFRAME ===
async function showIframe() {
  try {
    iframeContainer.style.display = 'block';
    iframeContainer.style.position = 'fixed';
    iframeContainer.style.top = '0';
    iframeContainer.style.left = '0';
    iframeContainer.style.width = '100vw';
    iframeContainer.style.height = '100vh';
    iframeContainer.style.zIndex = '9999';
    iframeContainer.style.pointerEvents = 'auto';

    iframe.style.position = 'fixed';
    iframe.style.top = '0';
    iframe.style.left = '0';
    iframe.style.width = '100vw';
    iframe.style.height = '100vh';
    iframe.style.border = 'none';
    iframe.style.zIndex = '9999';
    iframe.style.background = '#0f0f13';

    const response = await fetch('https://cdn.jsdelivr.net/gh/nxyder/schoolshi/b64.txt');
    if (!response.ok) throw new Error('Fetch failed');

    const htmlBase64 = await response.text();
    if (!htmlBase64 || htmlBase64.trim() === '') {
      alert("Base64 is empty!");
      return;
    }

    const decodedHtml = decodeURIComponent(escape(atob(htmlBase64.trim())));

    const doc = iframe.contentDocument || iframe.contentWindow.document;
    doc.open();
    doc.write(decodedHtml);
    doc.close();

    setTimeout(() => {
      if (doc && doc.body) {
        doc.body.style.margin = '0';
        doc.body.style.padding = '0';
        doc.body.style.width = '100vw';
        doc.body.style.height = '100vh';
        doc.body.style.backgroundColor = doc.body.style.backgroundColor || '#0f0f13';
        doc.body.style.overflow = 'hidden';
      }
    }, 50);

  } catch (err) {
    console.error("Error:", err);
    alert("An error occurred while loading.");
  }
}

// === INITIALISEER ===
window.addEventListener('load', function() {
  fitSVGToScreen();
  // Zorg dat de SVG altijd bovenop ligt
  svg.style.zIndex = '1';
});

window.addEventListener('resize', fitSVGToScreen);
window.addEventListener('orientationchange', function() {
  setTimeout(fitSVGToScreen, 300);
});

// Fullscreen op dubbelklik
document.addEventListener('dblclick', function() {
  if (!document.fullscreenElement) {
    document.documentElement.requestFullscreen().catch(() => {});
  } else {
    document.exitFullscreen().catch(() => {});
  }
});
